const leads = $('Fetch Leads to Follow Up').all().map(i => i.json);
const conversations = $('Fetch Recent Conversations').all().map(i => i.json);

if (leads.length === 0) {
  return [{ json: { no_leads: true, message: 'Aucun lead a relancer' } }];
}

// Enrich leads with conversation context
const enrichedLeads = leads.map(lead => {
  const leadConvos = conversations.filter(c => 
    c.contact_email === lead.email || c.contact_id === lead.id
  );

  const daysSinceContact = lead.last_contacted_at 
    ? Math.floor((Date.now() - new Date(lead.last_contacted_at).getTime()) / (24*60*60*1000))
    : 999;

  const totalMessages = leadConvos.reduce((sum, c) => sum + (c.message_count || 1), 0);

  // Determine follow-up urgency
  let urgency = 'normal';
  if (lead.qualification === 'hot' && daysSinceContact >= 1) urgency = 'high';
  if (lead.qualification === 'hot' && daysSinceContact >= 3) urgency = 'critical';
  if (lead.qualification === 'warm' && daysSinceContact >= 5) urgency = 'high';

  // Determine follow-up type
  let followUpType = 'nurture';
  if (lead.qualification === 'hot' && totalMessages < 3) followUpType = 'first_followup';
  else if (lead.qualification === 'hot' && totalMessages >= 3) followUpType = 'closing_push';
  else if (lead.qualification === 'warm' && totalMessages < 2) followUpType = 'value_offer';
  else if (lead.qualification === 'warm' && totalMessages >= 2) followUpType = 'social_proof';

  return {
    lead_id: lead.id,
    name: `${lead.first_name || ''} ${lead.last_name || ''}`.trim() || 'Prospect',
    email: lead.email,
    phone: lead.phone || null,
    source: lead.source,
    score: lead.lead_score,
    qualification: lead.qualification,
    interest: lead.tags || [],
    days_since_contact: daysSinceContact,
    total_messages: totalMessages,
    last_message: leadConvos[0]?.last_message || null,
    urgency,
    follow_up_type: followUpType,
    preferred_channel: lead.phone ? 'sms' : 'email'
  };
});

// Sort: critical first, then high, then normal
const sorted = enrichedLeads.sort((a, b) => {
  const urgencyOrder = { critical: 0, high: 1, normal: 2 };
  return (urgencyOrder[a.urgency] || 2) - (urgencyOrder[b.urgency] || 2);
});

return sorted.map(lead => ({ json: lead }));

